    const result = await api('account-register', { input: { provider: 'social-browser', externalAccountId: profileUrl, profileUrl, ...(company ? { loginConnectionId: owner.value, publishingProfileUrl: profileUrl } : {}), sender: { name: name.value.trim(), address: email.value.trim() }, purposes: ['social_publishing', ...(!company && ['linkedin', 'instagram'].includes(channel) ? ['social_messaging', 'manual_correspondence'] : [])], secretRef: 'env:OUTREACH_BROWSER_SESSION', executionPlacement: 'daytona-browser' } });
